"""Text-to-SQL harness: draft + execution-grounded verify/repair (max 2 policy calls).

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     one policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness (e.g. "system_prompt.md")
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


# ---------------------------------------------------------------- diagnostics

LITERAL = re.compile(r"'((?:[^']|'')*)'")
TABLE_REF = re.compile(r"\b(?:FROM|JOIN)\s+([A-Za-z_][A-Za-z0-9_]*)", re.I)
IDENT = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def _q(ident):
    return '"' + ident.replace('"', '""') + '"'


def _lit(s):
    return "'" + s.replace("'", "''") + "'"


def _run(env, sql):
    try:
        r = env.execute(sql, max_rows=20)
    except Exception as exc:  # never let probing break the task
        return {"ok": False, "error": str(exc), "rows": [], "columns": [], "n_rows": 0}
    if not isinstance(r, dict):
        return {"ok": False, "error": "bad result", "rows": [], "columns": [], "n_rows": 0}
    return r


def _tables(sql):
    seen, out = set(), []
    for t in TABLE_REF.findall(sql):
        k = t.lower()
        if k not in seen:
            seen.add(k)
            out.append(t)
    return out


def _columns(env, table):
    r = _run(env, "SELECT * FROM %s LIMIT 1" % _q(table))
    return list(r.get("columns") or []) if r.get("ok") else []


def _probe_literal(env, tables, cols_by_table, lit):
    """Find real cell values resembling a string literal used in the draft."""
    core = lit.strip()
    if not core:
        return []
    hits = []
    pat = "%" + core.replace("%", "").replace("_", " ") + "%"
    for t in tables:
        for c in cols_by_table.get(t, []):
            if not IDENT.match(c or ""):
                continue
            sql = (
                "SELECT DISTINCT %s.%s FROM %s WHERE CAST(%s.%s AS TEXT) LIKE %s LIMIT 3"
                % (_q(t), _q(c), _q(t), _q(t), _q(c), _lit(pat))
            )
            r = _run(env, sql)
            if r.get("ok") and r.get("rows"):
                vals = [row[0] for row in r["rows"] if row and row[0] is not None]
                if vals:
                    shown = ", ".join(repr(v) for v in vals[:3])
                    hits.append("%s.%s ~ %s -> %s" % (t, c, repr(lit), shown))
            if len(hits) >= 6:
                return hits
    return hits


def _predicate_counts(env, sql):
    """Row count with each top-level WHERE conjunct removed (isolates the killer filter)."""
    m = re.search(r"\bWHERE\b(.*?)(\bGROUP\s+BY\b|\bORDER\s+BY\b|\bLIMIT\b|$)", sql, re.I | re.S)
    if not m:
        return []
    body = m.group(1)
    parts = re.split(r"\s+AND\s+", body, flags=re.I)
    if len(parts) < 2:
        return []
    out = []
    for i, p in enumerate(parts):
        rest = [q for j, q in enumerate(parts) if j != i]
        alt = sql[: m.start(1)] + " AND ".join(rest) + " " + sql[m.end(1):]
        alt = re.sub(r"\bSELECT\b", "SELECT COUNT(*)", alt, count=1, flags=re.I)
        alt = re.sub(r"\bLIMIT\s+\d+\b", "", alt, flags=re.I)
        r = _run(env, alt)
        if r.get("ok") and r.get("rows"):
            out.append("without [%s]: %s rows" % (p.strip()[:120], r["rows"][0][0]))
    return out[:6]


def _antijoin_check(env, sql):
    """For NOT IN / NOT EXISTS over a two-column relation, test the other side too."""
    notes = []
    m = re.search(r"NOT\s+IN\s*\(\s*SELECT\s+([A-Za-z_][\w.]*)\s+FROM\s+([A-Za-z_]\w*)", sql, re.I)
    if not m:
        return notes
    col, tbl = m.group(1), m.group(2)
    cols = _columns(env, tbl)
    base = col.split(".")[-1].lower()
    others = [c for c in cols if c.lower() != base]
    if len(cols) != 2 or len(others) != 1:
        return notes
    other = others[0]
    union = "SELECT %s FROM %s UNION SELECT %s FROM %s" % (_q(col.split('.')[-1]), _q(tbl), _q(other), _q(tbl))
    alt = re.sub(r"NOT\s+IN\s*\(\s*SELECT[^)]*\)", "NOT IN (%s)" % union, sql, count=1, flags=re.I)
    alt = re.sub(r"\bSELECT\b", "SELECT COUNT(*)", alt, count=1, flags=re.I)
    alt = re.sub(r"\bLIMIT\s+\d+\b", "", alt, flags=re.I)
    r = _run(env, alt)
    if r.get("ok") and r.get("rows"):
        notes.append(
            "relation %s has two participant columns (%s, %s); excluding ids appearing on EITHER side gives %s rows"
            % (tbl, col, other, r["rows"][0][0])
        )
    return notes


def diagnose(task, env, sql):
    """Return (needs_repair, report_lines). Cheap, deterministic, read-only."""
    notes = []
    res = _run(env, sql)
    if not res.get("ok"):
        return True, ["EXECUTION ERROR: %s" % str(res.get("error"))[:300]]

    rows = res.get("rows") or []
    ncols = len(res.get("columns") or [])
    notes.append("Draft ran OK: %s rows x %s cols." % (res.get("n_rows", len(rows)), ncols))

    lits = [l.replace("''", "'") for l in LITERAL.findall(sql) if "%" not in l and "_" not in l]
    tables = _tables(sql)
    cols_by_table = {}
    needs = False

    if not rows:
        needs = True
        notes.append("The draft returns ZERO rows - very likely a wrong literal, wrong column or wrong join.")
        for t in tables[:4]:
            cols_by_table[t] = _columns(env, t)
        for lit in lits[:4]:
            hits = _probe_literal(env, tables[:4], cols_by_table, lit)
            if hits:
                notes.append("Real values resembling the literal (use these exactly, or LIKE):")
                notes.extend("  " + h for h in hits)
            else:
                notes.append("  no cell in the referenced tables resembles %r - the filter column may be wrong." % lit)
        notes.extend(_predicate_counts(env, sql))
        notes.extend(_antijoin_check(env, sql))
    else:
        # Non-empty but suspicious: unverified literals or a very narrow projection.
        if lits:
            for t in tables[:3]:
                cols_by_table[t] = _columns(env, t)
            for lit in lits[:3]:
                hits = _probe_literal(env, tables[:3], cols_by_table, lit)
                exact = any(repr(lit) in h for h in hits)
                if hits and not exact:
                    needs = True
                    notes.append("Literal %r does not appear verbatim; nearest real values:" % lit)
                    notes.extend("  " + h for h in hits)
        if ncols == 1 and re.search(r"\b(detail|details|information|all|everything|which|what)\b",
                                   task.get("question", ""), re.I):
            notes.append(
                "Projection is a single column while the question asks about an entity/details; "
                "consider SELECT <alias>.* unless a specific attribute is clearly requested."
            )
            needs = True
        notes.extend(_antijoin_check(env, sql))
        if any("EITHER side" in n for n in notes):
            needs = True

    if rows:
        notes.append("First rows: %s" % repr(rows[:3])[:400])
    return needs, notes


REPAIR_TEMPLATE = """Your previous query for this task needs revision.

Database: {db}

Schema:
{schema}

Question: {question}{hint}

Previous query:
```sql
{sql}
```

Execution diagnostics (from running the query and probing the real data):
{notes}

Write the corrected query. Rules:
- Match string values to how they are actually stored (case, spacing, padding); prefer LIKE '%value%' or LOWER(...) comparisons when the stored form differs from the question's wording.
- If a filter yields nothing, the column may be wrong: check the diagnostics for where the value really lives.
- For "no friends / no relationship" questions, exclude ids appearing on EITHER side of the relation table.
- If the question asks for an entity, its details, or "which X ..." without naming attributes, select all columns of that entity's table (alias.*), not just a name.
- Follow the hint's formulas and literal values exactly.
Return only the final query in one ```sql code block."""


def solve(task, env):
    schema = env.schema(task["db_id"])
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""

    user = "Database: %s\n\nSchema:\n%s\n" % (task["db_id"], schema)
    if desc.strip():
        user += "\nColumn descriptions:\n%s\n" % desc.strip()[:2000]
    user += "\nQuestion: %s" % task["question"]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]

    system = env.prompt("system_prompt.md")
    budget = getattr(env, "max_calls", 2) or 2
    reply = env.chat(
        [{"role": "system", "content": system}, {"role": "user", "content": user}],
        max_tokens=env.config.get("max_tokens", 800),
    )
    sql = extract_sql(reply)
    if not sql or budget < 2:
        return {"sql": sql}

    try:
        needs, notes = diagnose(task, env, sql)
    except Exception:
        return {"sql": sql}
    if not needs:
        return {"sql": sql}

    hint = ("\nHint: %s" % task["hint"]) if task.get("hint") else ""
    repair_user = REPAIR_TEMPLATE.format(
        db=task["db_id"], schema=schema, question=task["question"], hint=hint,
        sql=sql, notes="\n".join("- " + n for n in notes)[:3000],
    )
    try:
        reply2 = env.chat(
            [{"role": "system", "content": system}, {"role": "user", "content": repair_user}],
            max_tokens=env.config.get("max_tokens", 800),
        )
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    check = _run(env, sql2)
    if not check.get("ok"):
        return {"sql": sql}
    return {"sql": sql2}
